use anyhow::Result;use rusqlite::{Connection,params};use synara_events::Event;use std::path::Path;
pub struct Database{conn:Connection}
impl Database{pub fn open(path:impl AsRef<Path>)->Result<Self>{let c=Connection::open(path)?;let db=Self{conn:c};db.migrate()?;Ok(db)}pub fn open_memory()->Result<Self>{let c=Connection::open_in_memory()?;let db=Self{conn:c};db.migrate()?;Ok(db)}fn migrate(&self)->Result<()> {self.conn.execute_batch("PRAGMA foreign_keys=ON; CREATE TABLE IF NOT EXISTS events(event_id TEXT PRIMARY KEY,sequence INTEGER NOT NULL UNIQUE,timestamp TEXT NOT NULL,scope TEXT NOT NULL,entity_id TEXT NOT NULL,event_type TEXT NOT NULL,version INTEGER NOT NULL,payload TEXT NOT NULL); CREATE INDEX IF NOT EXISTS idx_events_sequence ON events(sequence); CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,name TEXT NOT NULL,root_path TEXT NOT NULL); CREATE TABLE IF NOT EXISTS threads(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,title TEXT); CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL,role TEXT NOT NULL,content TEXT NOT NULL);")?;Ok(())}pub fn append_event(&self,e:&Event)->Result<()>{self.conn.execute("INSERT INTO events(event_id,sequence,timestamp,scope,entity_id,event_type,version,payload) VALUES(?,?,?,?,?,?,?,?)",params![e.event_id.to_string(),e.sequence,e.timestamp.to_rfc3339(),e.scope,e.entity_id.to_string(),e.event_type,e.version,e.payload.to_string()])?;Ok(())}pub fn events_after(&self,seq: u64)->Result<Vec<Event>>{let mut s=self.conn.prepare("SELECT event_id,sequence,timestamp,scope,entity_id,event_type,version,payload FROM events WHERE sequence>? ORDER BY sequence")?;let rows=s.query_map([seq],|r|Ok((r.get::<_,String>(0)?,r.get::<_,u64>(1)?,r.get::<_,String>(2)?,r.get::<_,String>(3)?,r.get::<_,String>(4)?,r.get::<_,String>(5)?,r.get::<_,u32>(6)?,r.get::<_,String>(7)?)))?;let mut out=Vec::new();for row in rows{let(r)=row?;out.push(Event{event_id:r.0.parse()?,sequence:r.1,timestamp:chrono::DateTime::parse_from_rfc3339(&r.2)?.with_timezone(&chrono::Utc),scope:r.3,entity_id:r.4.parse()?,event_type:r.5,version:r.6,payload:serde_json::from_str(&r.7)?});}Ok(out)}}
